<script setup lang="ts">
import OperatorTaskCharts from './OperatorTaskCharts.vue'
const props=defineProps<{kind:'picking'|'packing';warehouseId:number;start:string;end:string}>()
const {t}=useI18n(),{bizErrorMessage}=useBizError()
const data=ref<any>(null),loading=ref(false),error=ref(''),page=ref(1)
const exporting=ref(false)
const download=async()=>{if(!data.value||exporting.value)return;exporting.value=true;error.value='';try{await downloadFile(`/api/warehouse/${props.kind}/report/operators/export?`+new URLSearchParams({start_date:props.start,end_date:props.end}),{headers:warehouseHeaders(props.warehouseId)},props.kind+'-operators.csv')}catch(e){error.value=bizErrorMessage(e as HttpRequestError)}finally{exporting.value=false}}
const rateMax=computed(()=>Math.max(1,data.value?.summary?.median_per_hour||0,...(data.value?.items||[]).map((row:any)=>row.per_hour||0)))
let generation=0
const load=async()=>{const seq=++generation;loading.value=true;error.value='';data.value=null;const result=await httpRequest<any>(`/api/warehouse/${props.kind}/report/operators`,{params:{start_date:props.start,end_date:props.end,page:page.value,per_page:50},headers:warehouseHeaders(props.warehouseId),onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}});if(seq===generation){data.value=result;loading.value=false}}
watch(()=>[props.warehouseId,props.start,props.end],()=>{page.value=1;load()});onMounted(load);onBeforeUnmount(()=>generation++)
const columns=computed(()=>[{key:'name',label:t('operator-report.operator')},{key:'quantity',label:t('operator-report.quantity'),type:'qty' as const,keepZero:true},{key:'tasks',label:t('operator-report.tasks'),type:'qty' as const,keepZero:true},{key:'hours',label:t('operator-report.hours'),align:'right' as const},{key:'rate',label:t('operator-report.rate'),align:'right' as const},{key:'untimed_tasks',label:t('operator-report.untimed'),type:'qty' as const,keepZero:true}])
const format=(value:number|null|undefined)=>value==null?'—':Number(value).toLocaleString(undefined,{maximumFractionDigits:1})
</script>
<template><WCard :title="t('nav.'+kind)" flush><template #actions><WButton size="sm" icon="download" :loading="exporting" :disabled="!data||loading" @click="download">{{t('goods.ui.export')}}</WButton></template><div v-if="data" class="operator-summary"><div><span>{{t('operator-report.quantity')}}</span><strong>{{format(data.summary.quantity)}}</strong></div><div><span>{{t('operator-report.tasks')}}</span><strong>{{format(data.summary.tasks)}}</strong></div><div><span>{{t('operator-report.operator')}}</span><strong>{{format(data.summary.operators)}}</strong></div><div><span>{{t('operator-report.median')}}</span><strong>{{format(data.summary.median_per_hour)}}</strong></div></div><WAlert v-if="error" tone="block" :title="error"/><WTable :rows="data?.items||[]" :columns="columns" row-key="operator_id" :loading="loading" inset><template #cell-hours="{row}">{{row.seconds?format(row.seconds/3600):'—'}}</template><template #cell-rate="{row}"><div class="rate-cell"><span v-if="row.per_hour!=null" class="rate-track"><i :style="{width:(100*row.per_hour/rateMax)+'%'}"/><b v-if="data.summary.median_per_hour!=null" :style="{left:(100*data.summary.median_per_hour/rateMax)+'%'}" :title="t('operator-report.median')+': '+format(data.summary.median_per_hour)"/></span><span class="rate">{{format(row.per_hour)}}</span></div></template></WTable><OperatorTaskCharts v-if="data?.task_chart" :data="data" :kind="kind"/><template #footer><WPagination :page="page" :page-size="50" :total="data?.total" show-total @update:page="value=>{page=value;load()}"/></template></WCard></template>
<style scoped>
.operator-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;padding:16px 24px;border-bottom:1px solid var(--w-line)}.operator-summary>div{display:flex;flex-direction:column;gap:2px}.operator-summary span{font-size:12px;line-height:18px;color:var(--w-text-2);font-weight:500}.operator-summary strong{font-size:20px;line-height:28px;font-weight:600}.rate{font-variant-numeric:tabular-nums;font-weight:600}:deep(.w-table){min-width:800px}:deep(th){font-size:12px;line-height:18px}:deep(td){padding-top:12px;padding-bottom:12px}@media(max-width:600px){.operator-summary{grid-template-columns:repeat(2,minmax(0,1fr))}}
.rate-cell{display:flex;align-items:center;justify-content:flex-end;gap:12px}.rate-track{position:relative;width:100px;height:8px;background:var(--w-surface-2)}.rate-track i{display:block;height:100%;background:#7855FE}.rate-track b{position:absolute;top:-4px;width:2px;height:16px;background:#A0A4B0}.rate{min-width:44px}</style>
